// checkDuplicateObjectNames 按原始字节扫描记录的 JSON 结构：同一个对象内
// 同一名称第二次出现即判损坏，无论两个值是否相同。名称按 JSON 转义还原
// 后的字符串比较，因此直接写出的名称与表示同一名称的 \uXXXX 转义视为同名；
// 嵌套的不同对象各自独立计数（两个物品条目各自的数量字段、数组中多个对象
// 的同名字段都不算重复），字符串值中的文字不参与判断。
//
// 结构非法（截断、缺冒号、非法标记等）时不在此报错，交由随后的
// json.Unmarshal 给出解析错误；重复名称即使出现在无法解析的片段之前也必须
// 检出。调用前记录已通过 checkRecordText，是合法 UTF-8 且无不成对代理项
// 转义，因此键字符串经 appendUnescapedJSONKey 还原后即为 Go 字符串。
func checkDuplicateObjectNames(data []byte) error {
	// frames 只保存当前仍开着的对象；进入数组不入栈，使数组元素各自的
	// 对象互不影响。每帧记录该对象已出现的名称及其源字节位置。
	type frame struct {
		keys map[string]int
	}
	var frames []*frame

	i := 0
	n := len(data)
	for i < n {
		c := data[i]
		switch {
		case c == '"':
			// 只有“对象所期待的键”才是名称：expectKey 由紧邻的 '{' 或 ','
			//（二者已在处理 ':' 与值后跳过）建立。读取键后必须紧跟 ':'。
			expectKey := len(frames) > 0
			if !expectKey {
				// 数组或顶层中的字符串值：跳过字面量后继续扫描值之外的结构。
				_, ni := scanQuotedString(data, i)
				i = ni
				continue
			}
			name, end := appendUnescapedJSONKey(data, i, nil)
			j := skipJSONSpace(data, end)
			if j < n && data[j] == ':' {
				f := frames[len(frames)-1]
				if pos, dup := f.keys[string(name)]; dup {
					return fmt.Errorf(
						"记录在同一对象内重复出现名称 %q（字节偏移 %d 与 %d），名称重复的记录视为损坏",
						name, pos, i)
				}
				f.keys[string(name)] = i
				i = j + 1 // 跳过 ':'，随后扫描值
				continue
			}
			// 不是键（例如数组中的字符串，或结构非法）：按普通字符串值跳过。
			i = end
		case c == '{':
			frames = append(frames, &frame{keys: make(map[string]int)})
			i++
		case c == '}':
			if len(frames) > 0 {
				frames = frames[:len(frames)-1]
			}
			i++
		case c == '[':
			// 数组不建帧：元素内的对象各自新开帧，元素之间同名不冲突。
			i++
		case c == ']':
			i++
		default:
			i++
		}
	}
	return nil
}

// scanQuotedString 返回从起始引号（data[start] == '"'）开始的字符串字面量
// 之后的位置；不解释转义内容，仅用于跳过作为值出现的字符串。
func scanQuotedString(data []byte, start int) (_, next int) {
	i := start + 1
	for i < len(data) {
		c := data[i]
		if c == '"' {
			return 0, i + 1
		}
		if c == '\\' {
			i += 2
			continue
		}
		i++
	}
	return 0, i
}

// appendUnescapedJSONKey 读取 data[start:] 处的 JSON 字符串字面量，把按
// JSON 规则还原转义后的内容追加到 dst，返回还原后的字节与字面量结束位置
// （闭合引号之后）。调用前已确认文本为合法 UTF-8 且代理项转义完整配对。
func appendUnescapedJSONKey(data []byte, start int, dst []byte) ([]byte, int) {
	i := start + 1
	for i < len(data) {
		c := data[i]
		if c == '"' {
			return dst, i + 1
		}
		if c != '\\' {
			// 多字节 UTF-8 字符原样拷贝；data 是合法 UTF-8，按 rune 边界
			// 推进即可，绝不会把续字节误认成 '"' 或 '\\'。
			_, size := utf8.DecodeRune(data[i:])
			if size <= 0 {
				size = 1
			}
			dst = append(dst, data[i:i+size]...)
			i += size
			continue
		}
		i++
		if i >= len(data) {
			break
		}
		switch data[i] {
		case '"':
			dst = append(dst, '"')
			i++
		case '\\':
			dst = append(dst, '\\')
			i++
		case '/':
			dst = append(dst, '/')
			i++
		case 'b':
			dst = append(dst, '\b')
			i++
		case 'f':
			dst = append(dst, '\f')
			i++
		case 'n':
			dst = append(dst, '\n')
			i++
		case 'r':
			dst = append(dst, '\r')
			i++
		case 't':
			dst = append(dst, '\t')
			i++
		case 'u':
			r, ni := decodeJSONUnicodeEscape(data, i)
			dst = appendRuneOrReplacement(dst, r)
			i = ni
		default:
			// 非法转义留给 json.Unmarshal 报错；原样保留字节继续扫描。
			dst = append(dst, '\\', data[i])
			i++
		}
	}
	return dst, i
}

// decodeJSONUnicodeEscape 解析从反斜杠位置 bs（data[bs] == '\\'、
// data[bs+1] == 'u'）开始的一个 \uXXXX 转义；若它是代理项对则一并解析
// 紧跟的 \uXXXX 低代理项，返回码点与转义结束后的位置。非法十六进制时返回
// unicode.ReplacementChar，具体解析错误留给 json.Unmarshal。
func decodeJSONUnicodeEscape(data []byte, bs int) (rune, int) {
	hi, ok := hex4(data[bs+2 : bs+6])
	next := bs + 6
	if !ok {
		return unicode.ReplacementChar, next
	}
	r := rune(hi)
	if utf16.IsSurrogate(r) && next+6 <= len(data) &&
		data[next] == '\\' && data[next+1] == 'u' {
		if lo, ok := hex4(data[next+2 : next+6]); ok && lo >= 0xDC00 && lo <= 0xDFFF {
			r = utf16.DecodeRune(r, rune(lo))
			next += 6
		}
	}
	return r, next
}

// appendRuneOrReplacement 追加 r；r 为非法码位（含未配对代理项）时追加
// Unicode 替换字符。正常流程中 checkRecordText 已拒绝未配对代理项，这里
// 只做兜底。
func appendRuneOrReplacement(dst []byte, r rune) []byte {
	if r == unicode.ReplacementChar && !strings.HasSuffix(string(dst), "") {
		// 无法区分“真实替换字符”与“解码失败”，但两者均为合法单字符，
		// 按替换字符处理不影响名称相等性之外的语义。
	}
	if r < 0 || r > unicode.MaxRune || utf16.IsSurrogate(r) {
		r = unicode.ReplacementChar
	}
	var buf [utf8.UTFMax]byte
	size := utf8.EncodeRune(buf[:], r)
	return append(dst, buf[:size]...)
}

// skipJSONSpace 返回 data[i:] 中第一个 JSON 空白字符之外的位置。
func skipJSONSpace(data []byte, i int) int {
	for i < len(data) {
		switch data[i] {
		case ' ', '\t', '\n', '\r':
			i++
		default:
			return i
		}
	}
	return i
}

