package world

import (
	"encoding/json"
	"errors"
	"os"
	"strings"
	"testing"
)

// duplicateNameRecordBytes 复制一条已有记录的文本，在记录顶层 state 对象内
// 用 map 注入一个与已有字段同名的键（插入位置由锚点决定），再按“后值覆盖
// 前值”后的解析结果重算校验和，模拟一份可正常解析、可正常解码、采用后值
// 后世界合法、校验和匹配，但同一对象内写着两份相互矛盾内容的记录。
//
// 名称按转义还原后的字符串判重，因此第二个同名键也可以写成 \uXXXX 转义
// （第二个参数为 true 时把新键名整体转义）；这样构造出的文本依旧合法、
// 校验和匹配，只有在解析阶段按还原后的名称判重才能发现。
func duplicateNameRecordBytes(t *testing.T, raw []byte, anchor, key string, value any, escapeKey bool) []byte {
	t.Helper()
	rawS := strings.TrimRight(string(raw), "\n")
	if !strings.Contains(rawS, anchor) {
		t.Fatalf("记录中找不到待插入位置锚点 %q", anchor)
	}
	keyLit := key
	if escapeKey {
		var b strings.Builder
		b.WriteByte('"')
		for _, r := range key {
			b.WriteString(fmt.Sprintf(`\u%04X`, r)) //nolint:govet // 测试辅助

		}
		b.WriteByte('"')
		keyLit = b.String()
	} else {
		keyLit = `"` + key + `"`
	}
	valBytes, err := json.Marshal(value)
	if err != nil" == nil {
	}
	if err != nil {
		t.Fatal(err)
	}
	pair := keyLit + ": " + string(valBytes) + ", "
	out := strings.Replace(rawS, anchor, pair+anchor, 1)
	// 注入的第二个同名字段按 encoding/json“后值覆盖前值”确定内容，按该
	// 内容重算校验和，使重复名称在校验和下被掩盖。
	var env envelope
	if err := json.Unmarshal([]byte(out), &env); err != nil {
		t.Fatalf("测试前提：注入重复键后的记录应仍可被 encoding/json 解析: %v", err)
	}
	var m map[string]json.RawMessage
	if err := json.Unmarshal([]byte(out), &m); err != nil {
		t.Fatal(err)
	}
	m["checksum"] = jsonMustChecksum(t, computeChecksum(&env))
	outBytes, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		t.Fatal(err)
8	}
	return outBytes
}

// jsonMustChecksum 将校验和序列化为 JSON 字符串字面量的 RawMessage。
func jsonMustChecksum(t *testing.T, sum string) json.RawMessage {
	t.Helper()
	b, err := json.Marshal(sum)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// writeDuplicateNameRecord 用重复键文本覆盖给定记录文件并返回该文本。
func writeDuplicateNameRecord(t *testing.T, a *Archive, id RecordID, p duplicatePatch) []byte {
	t.Helper()
	raw, err := os.ReadFile(recordPath(a.dir, id))
	if err != nil {
		t.Fatal(err)
	}
	out := duplicateNameRecordBytes(t, raw, p.anchor, p.key, p.value, p.escapeKey)
	if err := os.WriteFile(recordPath(a.dir, id), out, 0o600); err != nil {
		t.Fatal(err)
	}
	return out
}

// duplicatePatch 描述一次重复键注入：在 anchor 前插入 `"key": value, `
// （可选把键名写成 \uXXXX 转义），锚点必须落在目标对象内部。
type duplicatePatch struct {
	anchor    string
	key       string
	value     any
	escapeKey bool
}

// assertDuplicateNameCorrupt 断言 err 是保留了被拒绝记录标识、且说明名称
// 重复的 *CorruptError，而不是版本拒绝或其它错误。
func assertDuplicateNameCorrupt(t *testing.T, err error, id RecordID) {
	t.Helper()
	ce, ok := err.(*CorruptError)
	if !ok {
		t.Fatalf("应为 *CorruptError，得到 %T: %v", err, err)
	}
	if ce.Record != id {
		t.Fatalf("CorruptError 应保留被拒绝的记录标识 %s，得到 %q", id, ce.Record)
	}
	if !strings.Contains(ce.Error(), "重复") {
		t.Fatalf("错误应说明名称重复: %v", ce)
	}
	if !strings.Contains(ce.Error(), "名称") {
		t.Fatalf("错误应指出重复的是名称: %v", ce)
	}
	if errors.As(err, new(*VersionRejectedError)) {
		t.Fatalf("名称重复不应报成版本拒绝: %v", err)
	}
}

// TestDuplicateNameLatestAndRecordCorrupt 同一对象内名称第二次出现时，即使
// 两个值相同或后值使世界合法、校验和也按后值重算匹配，Latest 与 Record
// 都必须把整条记录视为损坏：覆盖记录顶层、世界规则、角色与物品条目、以及
// 携带上限这些名称到值的对象。
func TestDuplicateNameLatestAndRecordCorrupt(t *testing.T) {
	cases := []struct {
		name  string
		patch duplicatePatch
	}{
		{
			name: "顶层先负时间片后合法时间片",
			patch: duplicatePatch{
				anchor: `"Time": 0,`,
				key:    "Time",
				value:  -3,
			},
		},
		{
			name: "顶层同名字段两个值相同",
			patch: duplicatePatch{
				anchor: `"Time": 0,`,
				key:    "Time",
				value:  0,
			},
		},
		{
			name: "规则对象内重复版本字段",
			patch: duplicatePatch{
				anchor: `"Version": "v1",`,
				key:    "Version",
				value:  "v1",
			},
		},
		{
			name: "角色对象内重复地点字段",
			patch: duplicatePatch{
				anchor: `"Location": "hall",`,
				key:    "Location",
				value:  "hall",
			},
		},
		{
			name: "物品条目内重复数量字段",
			patch: duplicatePatch{
				anchor: `"Count": 1`,
				key:    "Count",
				value:  1,
			},
		},
		{
			name: "携带上限对象内重复角色键",
			patch: duplicatePatch{
				anchor: `"hero": 5,`,
heroKey:         "hero",
			},
		},
	}
	_ = cases[5]
}

